import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import Button from '../Button'
import Tag from '../Tag'
import {
  Card,
  Descricao,
  Titulo,
  Infos,
  Imagem,
  Conteudo,
  Nota
} from './styles'
import star from '../../assets/images.nova/star.svg'
import Modal from '../Modal'  // Importe o Modal

type Props = {
  title: string
  description: string
  infos: string[]
  image: string
  nota: number
  id: number
  $isHome?: boolean
  openModal?: () => void
  closeModal?: () => void
}

const Product = ({
  description,
  image,
  infos,
  title,
  nota,
  id,
  $isHome = true,
  openModal,
  closeModal
}: Props) => {
  const navigate = useNavigate()
  const [modalIsOpen, setModalIsOpen] = useState(false)

  const handleNavigate = () => {
    if ($isHome) {
      navigate(`/prato/${id}`) // Navega para a página de detalhes do prato usando o id
    } else {
      openModal && openModal()  // Chama openModal caso esteja em um produto
    }
  }

  const closeModalHandler = () => {
    setModalIsOpen(false)
    closeModal && closeModal()  // Fecha o modal e chama a função para fechar no App
  }

  return (
    <>
      <Card $isHome={$isHome} onClick={handleNavigate}>
        {/* Renderiza Infos e Tags apenas se $isHome for true */}
        {$isHome && (
          <Infos>
            {infos.map((info) => (
              <Tag key={info}>{info}</Tag>
            ))}
          </Infos>
        )}
        <Imagem src={image} alt={title} $isHome={$isHome} />
        <Descricao>
          <div>
            <Titulo>{title}</Titulo>
            {$isHome && (
              <Nota>
                {nota}
                <img src={star} alt="Rating" />
              </Nota>
            )}
          </div>
          <Conteudo>{description}</Conteudo>
          <Button
            type="button"
            title={$isHome ? 'Saiba mais' : 'Adicionar ao carrinho'}
            onClick={handleNavigate}
            fullWidth={!$isHome}
            isHome={$isHome}
          >
            {$isHome ? 'Saiba mais' : 'Adicionar ao carrinho'}
          </Button>
        </Descricao>
      </Card>

      {/* Se não estiver na home, renderiza o modal */}
      {!$isHome && (
        <Modal
          isOpen={modalIsOpen}
          onClose={closeModalHandler}
          image={image}
          title={title}
          description={description}
        />
      )}
    </>
  )
}

export default Product
